CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 INT DEFAULT 'd', c1 INTEGER CHECK(c1 IS NULL OR length(c1) < 40), c2 BLOB, c3 INT, c4 VARCHAR(10));
INSERT OR IGNORE INTO t0(c0, c1, c2, c3, c4) VALUES(NULL, 9223372036854775807, x'c7f3', 'pi', 883.1);
INSERT OR IGNORE INTO t0(c0, c1, c2, c3, c4) VALUES(x'83e5095b74be', 'nu', 479, 2.5, 1);
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 REAL NOT NULL DEFAULT 0, c1 BLOB, c2, c3 REAL, ref INTEGER REFERENCES t0(id));
SELECT length('Lambda'), upper('Lambda'), lower('Lambda'), substr('Lambda', 2, 1), instr('Lambda', ' pad '), replace('Lambda', 'e', 'XY'), trim('Lambda'), ltrim('Lambda', 'ab'), hex('Lambda'), quote('Lambda'), unicode('Lambda'), 'Lambda' LIKE '%', 'Lambda' GLOB '?', char(67, 335), 'Lambda' || ' pad ', 'Lambda' < ' pad ', 'Lambda' = ' pad ' COLLATE NOCASE;
SELECT length('sigma'), upper('sigma'), lower('sigma'), substr('sigma', 2, 4), instr('sigma', 'x_y'), replace('sigma', 'é', ''), trim('sigma'), ltrim('sigma', 'ab'), hex('sigma'), quote('sigma'), unicode('sigma'), 'sigma' LIKE '_', 'sigma' GLOB '?', char(82, 414), 'sigma' || 'x_y', 'sigma' < 'x_y', 'sigma' = 'x_y' COLLATE NOCASE;
SELECT length('sigma'), upper('sigma'), lower('sigma'), substr('sigma', 3, 2), instr('sigma', 'sigma'), replace('sigma', 'a', '_'), trim('sigma'), ltrim('sigma', 'ab'), hex('sigma'), quote('sigma'), unicode('sigma'), 'sigma' LIKE '%', 'sigma' GLOB '*[a-m]*', char(69, 383), 'sigma' || 'sigma', 'sigma' < 'sigma', 'sigma' = 'sigma' COLLATE NOCASE;
SELECT length('-7'), upper('-7'), lower('-7'), substr('-7', 1, 5), instr('-7', 'omega'), replace('-7', 'a', 'XY'), trim('-7'), ltrim('-7', 'ab'), hex('-7'), quote('-7'), unicode('-7'), '-7' LIKE '_', '-7' GLOB '*', char(72, 772), '-7' || 'omega', '-7' < 'omega', '-7' = 'omega' COLLATE NOCASE;
SELECT length(' pad '), upper(' pad '), lower(' pad '), substr(' pad ', 1, 4), instr(' pad ', '-7'), replace(' pad ', 'é', 'XY'), trim(' pad '), ltrim(' pad ', 'ab'), hex(' pad '), quote(' pad '), unicode(' pad '), ' pad ' LIKE '%é%', ' pad ' GLOB 'a*', char(78, 819), ' pad ' || '-7', ' pad ' < '-7', ' pad ' = '-7' COLLATE NOCASE;
SELECT id, typeof((typeof('sigma') % x'03')), c0 IN (iif(c0, -5 IN (-1, NULL, 244), NULL), NULL, 296) FROM t0 ORDER BY id, c0 DESC, c1 DESC, c2, c3, c4;
SELECT CAST((CASE WHEN NULL THEN 'upsilon' ELSE -1 END & (x'46459f' / NULL)) AS INTEGER), NOT typeof(typeof(x'7767ef59'));
